 " ) if "배운점" in self . content : print ( "배운 점:" ) for i , lesson in enumerate ( self . content [ "배운점" ], 1 ): print ( f " { i } . { lesson } " ) print () if "앞으로의목표" in self . content : print ( "앞으로의 목표:" ) for goal in self . content [ "앞으로의목표" ]: print ( f " 🎯 { goal } " ) # 사용 예 retrospective = LearningRetrospective ( "박준호" ) retrospective . add_journey ( "print()만 알던 초보자" , "클래스와 파일 입출력까지 다루는 학습자" ) retrospective . add_challenge ( "클래스 개념이 너무 어려웠어요" , "작은 예제부터 만들어보며 차근차근 이해했어요" ) retrospective . add_lessons ([ "파이썬 기초부터 응용까지 배웠어요" , "문제를 단계별로 나누어 풀 수 있게 되었어요" , "프로그래밍으로 실제 문제를 해결할 수 있다는 걸 알았어요" ]) retrospective . add_future ([ "웹개발 배우기" , "데이터 분석 프로젝트 하기" , "오픈소스 프로젝트 기여하기" ]) retrospective . print_retrospective ()
